                result = (result * p) % pcon;
            }
        } else {
            long prod = 1;
            long first_found = 0;
            long index_jj = 0;
            for (long i = 1; i < p; ++i) {
                prod = (prod * k) % p;
                if ((prod % p) == 1 && first_found == 0) {
                    index_jj = i;
                    first_found = 1;
                }
            }
            result = 1;
            long t = (p - 1) / index_jj;
            if (k == 1) {
                result = 1;
                for (long i = 0; i < p; ++i) {
                    result = (result * p) % pcon;
                }
